'use strict';
const C=AerockCore, $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const demo=new URLSearchParams(location.search).get('demo')==='1';
function newId(){if(crypto.randomUUID)return crypto.randomUUID();let a=crypto.getRandomValues(new Uint8Array(16));a[6]=(a[6]&15)|64;a[8]=(a[8]&63)|128;let h=Array.from(a,x=>x.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`}
const PARTS=['리드기타','리듬기타','베이스','키보드(메인)','키보드(신디)','드럼','메인보컬','서브보컬'];
const roleNames={president:'회장',vicepresident:'부회장',leader1:'합주부장',leader2:'합주부장',leader3:'합주부장',member:'부원',treasurer:'총무'};
const icons={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',events:'M5 3v4m14-4v4M3 10h18M3 5h18v16H3Z',free:'M9 18V5l11-2v13M9 9l11-2M9 18c0 4-6 4-6 1s6-4 6-1m11-2c0 4-6 4-6 1s6-4 6-1',schedule:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v6l4 2',profile:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-3c0-6 16-6 16 0v3'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.events}"/></svg>`;
let client,me,profiles=[],records=[],page=sessionStorage.getItem('aerock-v2-page')||'home',selectedEvent=null,eventTab='songs',onlyMine=false;
let weekStart=C.isoDate(),brush=sessionStorage.getItem('aerock-schedule-brush')||'free',editing=false,draftSlots={},dirty=false,availabilityRevision=null;
let savedSlots={},scheduleSaving=false;
if(!Object.hasOwn(C.states,brush))brush='free';
let toastTimer,busy=false,realtimeTimer;
const rows=k=>records.filter(r=>r.kind===k&&!r.payload.deleted).map(r=>({...r.payload,id:r.id,revision:r.revision,owner_id:r.owner_id,updated_at:r.updated_at}));
const raw=id=>records.find(r=>r.id===id), data=id=>{let r=raw(id);return r?{...r.payload,id:r.id,revision:r.revision,owner_id:r.owner_id}:null};
const name=id=>profiles.find(p=>p.id===id)?.display_name||'부원';
const chair=()=>['president','vicepresident'].includes(me?.role), leader=()=>me?.role?.startsWith('leader'),manage=s=>chair()||(leader()&&s.manager_id===me.id);
const badge=(s,orange=false)=>`<span class="badge ${orange?'orange':''}">${esc(s)}</span>`;
const btn=(label,action,id='',cls='secondary')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const empty=(title,description='')=>`<div class="empty"><strong>${title}</strong>${description}</div>`;
function toast(s){if($('#modal').open){let error=$('#modalError');if(!error){error=document.createElement('p');error.id='modalError';error.className='error';error.setAttribute('role','alert');$('#modalForm').append(error)}error.textContent=s}$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}
function formatDate(s,withTime=false){if(!s)return '미정';return new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',weekday:'short',...(withTime?{hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(s))}
function time(s){return new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(s))}
function dd(s){let n=Math.round((new Date(C.isoDate(new Date(s))+'T00:00:00+09:00')-new Date(C.isoDate()+'T00:00:00+09:00'))/864e5);return n===0?'D-DAY':n>0?'D-'+n:'종료'}
function localInput(s){if(!s)return '';let d=new Date(new Date(s).getTime()+9*36e5);return d.toISOString().slice(0,16)}
function field(label,name,value='',type='text',required=false){return `<div class="field"><label for="f_${name}">${label}</label><input id="f_${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></div>`}
function textarea(label,name,value=''){return `<div class="field"><label for="f_${name}">${label}</label><textarea id="f_${name}" name="${name}" maxlength="3000">${esc(value)}</textarea></div>`}
function select(label,n,options,value=''){return `<div class="field"><label for="f_${n}">${label}</label><select id="f_${n}" name="${n}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`}
function openModal(title,body,submitLabel,submit){let d=$('#modal');d.innerHTML=`<form id="modalForm"><header><h2>${title}</h2><button type="button" data-action="close" aria-label="닫기">×</button></header>${body}<footer>${btn('닫기','close','','subtle')}${submitLabel?`<button type="submit">${submitLabel}</button>`:''}</footer></form>`;d.showModal();$('#modalForm').onsubmit=async e=>{e.preventDefault();if(typeof submit!=='function'||busy)return;busy=true;let b=e.submitter;if(b)b.disabled=true;try{await submit(new FormData(e.target),e.target)}catch(err){toast(err.message)}finally{busy=false;if(b)b.disabled=false}}}
function closeModal(){$('#modal').close()}
function poster(e,cls=''){return `<div class="poster ${cls}">${e.poster?`<img src="${esc(e.poster)}" alt="${esc(e.title)} 공연 포스터">`:`<div class="placeholder">${icon('events')}포스터 제작중입니다</div>`}</div>`}
function nav(){return [['home','홈'],['events','공연'],['free','프리폼'],['schedule','내 시간표'],['profile','마이페이지']].map(([p,l])=>`<button type="button" class="nav ${page===p?'active':''}" data-action="nav" data-id="${p}" ${page===p?'aria-current="page"':''}>${icon(p)}${l}</button>`).join('')}
function render(){
 if(!['home','events','free','schedule','profile'].includes(page))page='home';sessionStorage.setItem('aerock-v2-page',page);
 if(!me)return loginView();if(me.status!=='active')return pendingView();
 const titles={home:'우리의 다음 무대를 위해',events:'공연',free:'프리폼',schedule:'내 시간표',profile:'마이페이지'};
 $('#app').innerHTML=`${demo?`<div class="demo-banner"><span>시안 · 샘플 데이터 <span class="demo-help">— 실제 회원 데이터와 연결되지 않습니다</span></span><select aria-label="미리보기 역할" id="demoRole">${profiles.filter(p=>p.role==='member').map(p=>`<option value="${p.id}" ${me.id===p.id?'selected':''}>부원 · ${esc(p.display_name)}</option>`).join('')}<option value="president" ${chair()?'selected':''}>회장 화면</option><option value="leader1" ${leader()?'selected':''}>합주부장 화면</option></select>${btn('초기화','resetDemo','','subtle small')}</div>`:''}<div class="shell"><aside class="sidebar"><div class="wordmark">AER<span>O</span>CK<span>.</span></div><div class="brand-sub">MAKE OUR NEXT STAGE</div><nav aria-label="주 메뉴">${nav()}</nav><div class="side-bottom"><div class="row"><div class="avatar">${esc(me.display_name?.slice(0,1)||'A')}</div><div><strong>${esc(me.display_name)}</strong><div class="muted smalltext">${roleNames[me.role]||'부원'}</div></div></div><div style="margin-top:15px">${btn('로그아웃','logout','','subtle small')}</div></div></aside><main class="main"><div class="topbar"><div class="breadcrumb">AEROCK CLUB <span class="muted"> / ${titles[page]}</span></div><div class="wordmark brand-mobile">AER<span>O</span>CK.</div><div class="row"><span class="muted smalltext">${formatDate(new Date())}</span>${btn('새로고침','refresh','','subtle small')}</div></div><div id="content"></div><div class="footnote">AEROCK · MAKE OUR NEXT STAGE</div></main><nav class="mobile-nav" aria-label="모바일 메뉴">${nav()}</nav></div>`;
 const content=$('#content');content.innerHTML=page==='home'?homeView():page==='events'?eventsView():page==='free'?freeView():page==='schedule'?scheduleView():profileView();
 if(page==='schedule')bindPaint();
 $('#demoRole')?.addEventListener('change',e=>{if(dirty){e.target.value=me.role==='member'?me.id:me.role;toast('시간표를 먼저 저장해주세요.');return}me=profiles.find(p=>p.id===e.target.value||p.role===e.target.value);sessionStorage.setItem('aerock-demo-persona',me.id);loadScheduleDraft();render()});
}
function activeEvents(){return rows('event').sort((a,b)=>new Date(a.date)-new Date(b.date))}
function mySongs(){return rows('song').filter(s=>(s.entries||[]).some(e=>e.user_id===me.id))}
function practiceUsers(r){return [...new Set((r.segments||[]).flatMap(seg=>C.members(data(seg.song_id)||{})))]}
function myPractices(){return rows('rehearsal').filter(r=>r.status!=='취소'&&practiceUsers(r).includes(me.id)&&r.segments.some(s=>new Date(s.end)>new Date())).sort((a,b)=>new Date(a.segments[0].start)-new Date(b.segments[0].start))}
function responseFor(r,uid=me.id){let a=data('response:'+r.id+':'+uid);return a?.schedule_revision===r.revision?a:null}
function practiceCard(r,compact=false){let mine=r.segments.filter(s=>C.members(data(s.song_id)||{}).includes(me.id));if(!mine.length)mine=r.segments;let first=[...mine].sort((a,b)=>new Date(a.start)-new Date(b.start))[0];let response=responseFor(r);return `<article class="card next-rehearsal"><div class="row between"><span class="eyebrow">${compact?'NEXT REHEARSAL':'REHEARSAL'}</span>${badge(r.status||'예약 완료',r.status!=='취소')}</div><div class="metric-date">${formatDate(first.start)}</div><div class="rehearsal-time">${time(first.start)} — ${time([...mine].sort((a,b)=>new Date(b.end)-new Date(a.end))[0].end)}</div><div class="detail-line"><strong>${esc(r.location)}</strong></div>${mine.map(s=>`<div class="detail-line">${time(s.start)}–${time(s.end)} · ${esc(data(s.song_id)?.title||'삭제된 곡')} <span class="muted">/ ${esc(s.room)}</span></div>`).join('')}<div class="row between" style="margin-top:18px">${badge(response?.status||'확인 필요',!response||response.status==='조율 요청')}${btn('상세 보기 ↗','practiceDetail',r.id,'subtle small')}</div>${practiceUsers(r).includes(me.id)&&r.status!=='취소'?`<div class="actions">${btn('확인했어요','ack',r.id,response?.status==='확인 완료'?'secondary':'')}${btn('조율이 필요해요','request',r.id,'secondary')}</div>`:''}</article>`}
function homeView(){let events=activeEvents().filter(e=>dd(e.date)!=='종료'),event=events[0],ps=myPractices(),songs=mySongs();return `<div class="intro"><div class="eyebrow">YOUR BAND, YOUR STAGE</div><h1>${esc(me.display_name)}님, 다음 무대를 준비해요<span class="accent">.</span></h1><p>함께할 곡부터 다음 합주까지, 한곳에서 확인하세요.</p></div><div class="home-grid"><div><article class="card hero"><div class="hero-copy"><span class="eyebrow">UPCOMING STAGE</span><div class="countdown">${event?dd(event.date):'NEXT'}</div><h2>${esc(event?.title||'다음 무대를 기다려요')}</h2><p class="muted smalltext">${event?formatDate(event.date)+' · '+esc(event.location||'장소 미정'):'공연이 등록되면 이곳에 표시돼요.'}</p>${btn(event?'공연 살펴보기 ↗':'공연 목록 보기 ↗',event?'event':'nav',event?.id||'events','secondary small')}</div>${poster(event||{})}</article>${events.length>1?`<div class="card" style="margin-top:18px">${events.slice(1,3).map(e=>`<div class="list-row"><div>${badge(dd(e.date),true)} <strong>${esc(e.title)}</strong></div>${btn('보기','event',e.id,'subtle small')}</div>`).join('')}</div>`:''}<div class="section-head"><h2>내 참여곡 <span class="muted">${songs.length}</span></h2>${btn('전체 보기 ↗','nav','profile','subtle small')}</div><div class="card">${songs.length?songs.slice(0,4).map(s=>`<div class="list-row"><div><p>${esc(data(s.event_id)?.title||'프리폼')}</p><h3>${esc(s.title)}</h3><p>${s.entries.filter(e=>e.user_id===me.id).map(e=>esc(e.part)+' · '+(e.status==='confirmed'?'참여 확정':'신청 중')).join(' / ')}</p></div>${btn('보기','songDetail',s.id,'subtle small')}</div>`).join(''):empty('아직 참여한 곡이 없어요','공연이나 프리폼에서 함께할 곡을 찾아보세요.')}</div></div><div>${ps.length?practiceCard(ps[0],true):`<div class="card"><div class="eyebrow">NEXT REHEARSAL</div><h2>내 다음 합주</h2>${empty('예정된 합주가 없어요','합주부장이 일정을 등록하면 여기에 표시돼요.')}</div>`}<div class="section-head"><h2>다가오는 마감</h2></div><div class="card">${events.flatMap(e=>[['곡 신청',e.song_deadline],['세션 신청',e.session_deadline]].filter(([,d])=>new Date(d)>new Date()).map(([type,d])=>`<div class="list-row"><div><p>${esc(e.title)}</p><h3>${type} 마감</h3><p>${formatDate(d,true)}</p></div>${badge(dd(d),true)}</div>`)).join('')||'<p class="muted">현재 예정된 모집 마감이 없어요.</p>'}</div>${leader()?`<div class="card"><h3>내 담당곡</h3><p class="muted">${rows('song').filter(s=>s.manager_id===me.id).length}곡의 준비를 함께하고 있어요.</p>${btn('담당곡 관리 →','managed','','secondary')}</div>`:''}</div></div>`}
function songCard(s,i){const full=(s.entries||[]).filter(e=>e.status==='confirmed');return `<article class="card song-card" data-action="songDetail" data-id="${s.id}" tabindex="0" role="button" aria-label="${esc(s.title)} 상세"><span class="song-status">${badge(s.event_id?s.status:'프리폼',s.status==='공연 확정')}</span><div class="song-index">${String(i+1).padStart(2,'0')}</div><h3>${esc(s.title)}</h3><p class="muted smalltext">${esc(s.artist)}</p><div class="parts">${s.parts.map(p=>`<span class="part ${full.some(e=>e.part===p)?'':'open'}">${esc(p)}${full.some(e=>e.part===p)?' ✓':' +'}</span>`).join('')}</div><div class="progress"><i style="width:${full.length/s.parts.length*100}%"></i></div><div class="row between smalltext"><span class="muted">${full.length}/${s.parts.length} 파트 확정</span><span>${s.event_id?esc(s.manager_id?name(s.manager_id):'담당 미배정'):esc((s.notes||'자유롭게 함께해요').slice(0,65))}</span></div></article>`}
function eventsView(){if(!selectedEvent)return `<div class="intro row between"><div><div class="eyebrow">OUR STAGES</div><h1>공연</h1><p>무대를 고르고, 함께 연주할 곡을 만나보세요.</p></div>${chair()?btn('+ 공연 만들기','eventForm','',''):''}</div>${onlyMine?`<div class="note">내 담당곡만 표시 중 ${btn('전체 공연 보기','allEvents','','subtle small')}</div><div class="grid three" style="margin-top:20px">${rows('song').filter(s=>s.manager_id===me.id).map(songCard).join('')||empty('담당 곡이 없어요')}</div>`:`<div class="grid three">${activeEvents().map(e=>`<article class="card">${poster(e,'poster-top')}<div class="row between">${badge(dd(e.date),true)}<span class="muted smalltext">${rows('song').filter(s=>s.event_id===e.id).length}곡</span></div><h2 style="margin-top:18px">${esc(e.title)}</h2><p class="muted smalltext">${formatDate(e.date,true)}<br>${esc(e.location||'장소 미정')}</p>${btn('공연 살펴보기 ↗','event',e.id,'secondary')}</article>`).join('')||empty('아직 등록된 공연이 없어요',chair()?'첫 공연을 만들어 곡을 모집해보세요.':'회장단이 공연을 등록하면 확인할 수 있어요.')}</div>`}`;
 let e=data(selectedEvent);if(!e){selectedEvent=null;return eventsView()}let songs=rows('song').filter(s=>s.event_id===e.id),open=new Date(e.song_deadline)>new Date();return `${btn('← 공연 목록','eventBack','','subtle small')}<div class="intro row between" style="margin-top:24px"><div><div class="eyebrow">${dd(e.date)} · OUR STAGE</div><h1>${esc(e.title)}</h1><p>${formatDate(e.date,true)} · ${esc(e.location||'장소 미정')}</p></div><div class="row">${chair()?btn('공연 수정','eventForm',e.id,'secondary'):''}${open?btn('+ 곡 신청','songForm',e.id,''):badge('곡 신청 마감')}</div></div><div class="note">곡 신청 마감 <strong>${formatDate(e.song_deadline,true)}</strong>　 /　세션 신청 마감 <strong>${formatDate(e.session_deadline,true)}</strong></div>${e.notes?`<p class="muted" style="margin-top:15px;white-space:pre-wrap">${esc(e.notes)}</p>`:''}<div class="tabs">${[['songs','곡 목록'],['table','세션표'],['practices','합주 일정']].map(([id,t])=>`<button type="button" data-action="eventTab" data-id="${id}" class="${eventTab===id?'active':''}">${t}</button>`).join('')}</div>${eventTab==='songs'?`<div class="grid three">${songs.map(songCard).join('')||empty('첫 곡을 신청해보세요','함께 연주하고 싶은 곡을 등록해주세요.')}</div>`:eventTab==='table'?sessionTable(songs):`<div class="row between" style="margin-bottom:20px"><span class="muted">예약된 합주와 참여자 응답을 확인하세요.</span>${chair()||leader()?btn('+ 합주 일정 잡기','planner',e.id,''):''}</div><div class="grid">${rows('rehearsal').filter(r=>r.segments.some(seg=>songs.some(s=>s.id===seg.song_id))).map(r=>practiceCard(r)).join('')||empty('등록된 합주가 없어요')}</div>`}`}
function sessionTable(songs){let parts=[...new Set(songs.flatMap(s=>s.parts))];return songs.length?`<div class="table-wrap"><table><thead><tr><th>곡 / 아티스트</th>${parts.map(p=>`<th>${esc(p)}</th>`).join('')}<th>담당</th></tr></thead><tbody>${songs.map(s=>`<tr><td>${btn(esc(s.title),'songDetail',s.id,'subtle small')}<br><span class="muted">${esc(s.artist)}</span></td>${parts.map(p=>{let es=s.entries.filter(x=>x.part===p);return `<td>${!s.parts.includes(p)?'<span class="blank">—</span>':es.length?es.map(x=>esc(name(x.user_id))+(x.status==='pending'?' <span class="accent">신청</span>':'')).join('<br>'):'<span class="accent">모집 중</span>'}</td>`}).join('')}<td>${esc(s.manager_id?name(s.manager_id):'미배정')}</td></tr>`).join('')}</tbody></table></div>`:empty('등록된 곡이 없어요')}
function freeView(){return `<div class="intro row between"><div><div class="eyebrow">PLAY WHAT YOU LOVE</div><h1>프리폼</h1><p>이 곡, 같이 해볼래요? 부담 없이 모이고 자유롭게 연주해요.</p></div>${btn('+ 곡 등록','songForm','','')}</div><div class="note">빈 파트에 바로 참여할 수 있어요. 합주는 참여자들이 원할 때 자유롭게 진행해요.</div><div class="grid three" style="margin-top:24px">${rows('song').filter(s=>!s.event_id).map(songCard).join('')||empty('함께하고 싶은 곡이 있나요?','곡과 합주 목적을 적고 함께할 세션을 찾아보세요.')}</div>`}
function profileView(){let songs=mySongs();return `<div class="intro"><div class="eyebrow">MY AEROCK</div><h1>마이페이지</h1></div><div class="card row between"><div class="row"><div class="avatar">${esc(me.display_name.slice(0,1))}</div><div><h3 style="margin:0">${esc(me.display_name)}</h3><span class="muted">${roleNames[me.role]||'부원'}</span></div></div><div class="row">${btn('이름 수정','name','','secondary')}${btn('로그아웃','logout','','subtle')}</div></div>${chair()?`<div class="section-head"><h2>가입 승인</h2>${btn('대기 회원 확인','members','','secondary small')}</div><div id="pendingMembers"></div>`:''}<div class="section-head"><h2>내 신청·참여곡</h2></div>${sessionTable(songs)}<div class="section-head"><h2>내 합주 일정</h2></div><div class="grid">${myPractices().map(r=>practiceCard(r)).join('')||empty('예정된 합주가 없어요')}</div>`}
function loadScheduleDraft({keepEditing=false}={}){let r=raw('availability:'+me.id);draftSlots=C.dateSlots(r?.payload.slots||{});savedSlots=structuredClone(draftSlots);availabilityRevision=r?.revision??null;dirty=false;if(!keepEditing)editing=false}
function scheduleDirty(){const keys=new Set([...Object.keys(savedSlots),...Object.keys(draftSlots)]);dirty=[...keys].some(k=>(savedSlots[k]||'unknown')!==(draftSlots[k]||'unknown'));return dirty}
function slotValue(key){const split=key.lastIndexOf(':'),col=key.slice(0,split),i=Number(key.slice(split+1));return C.availability(draftSlots,col,i)}
function updateSaveState(){const discard=document.querySelector('[data-action="discardSchedule"]');if(discard)discard.disabled=scheduleSaving||!dirty;const b=document.querySelector('[data-action="saveSchedule"]');if(b){b.disabled=scheduleSaving||!dirty;b.textContent=scheduleSaving?'저장 중…':'저장하기'}const status=$('#saveState');if(status){status.textContent=dirty?'저장하지 않은 변경사항이 있어요 · 저장하기를 눌러 서버에 반영하세요':'변경사항이 없어요';status.className='smalltext '+(dirty?'accent':'muted')}}
async function saveSchedule(){
 if(scheduleSaving||!dirty)return;
 scheduleSaving=true;updateSaveState();
 try{
  try{await save('availability','availability:'+me.id,{slots:structuredClone(draftSlots)},availabilityRevision)}
  catch(error){
   if(!error.message.includes('다른 사람이 수정'))throw error;
   await load();const latest=raw('availability:'+me.id),result=C.mergeSchedule(savedSlots,draftSlots,latest?.payload.slots||{});
   savedSlots=C.dateSlots(latest?.payload.slots||{});draftSlots=result.merged;availabilityRevision=latest?.revision??null;scheduleDirty();
   if(result.conflicts.length){render();throw new Error('다른 기기에서 같은 시간 '+result.conflicts.length+'칸을 수정했어요. 내 입력을 유지했으니 확인 후 저장하기를 다시 누르세요. 서버 값을 사용하려면 변경 취소를 누르세요.')}
   await save('availability','availability:'+me.id,{slots:structuredClone(draftSlots)},availabilityRevision);
  }
  loadScheduleDraft({keepEditing:true});render();toast(demo?'이 브라우저에 샘플 시간표를 저장했어요':'시간표를 서버에 저장했어요');
 }finally{scheduleSaving=false;updateSaveState()}
}
function scheduleView(){
 const dates=Array.from({length:7},(_,i)=>C.dateAdd(weekStart,i)),days=['일','월','화','수','목','금','토'];
 return `<div class="intro"><div class="eyebrow">MAKE TIME FOR MUSIC</div><h1>내 시간표</h1><p>날짜별로 가능한 시간을 입력하세요. 입력하지 않은 시간은 미정이에요.</p></div><div class="card"><div class="toolbar schedule-toolbar"><div class="row">${btn('← 이전 7일','scheduleWeek','-7','subtle small')}<label for="weekStart">시작일</label><input id="weekStart" type="date" value="${weekStart}" style="width:170px">${btn('다음 7일 →','scheduleWeek','7','subtle small')}</div><div class="row">${btn(editing?'편집 종료':'시간표 편집','editSchedule','','secondary')}<button type="button" data-action="saveSchedule" ${scheduleSaving||!dirty?'disabled':''}>${scheduleSaving?'저장 중…':'저장하기'}</button></div></div><div class="brushes">${Object.entries(C.states).map(([k,v])=>`<button type="button" data-action="brush" data-id="${k}" class="${brush===k?'selected':''}" aria-pressed="${brush===k}">${v}</button>`).join('')}</div><p class="muted smalltext">${editing?'선택한 항목은 계속 유지돼요. 같은 상태의 칸을 다시 누르면 미정으로 해제돼요. 드래그로 여러 칸을 바꿀 수 있어요.':'편집 버튼을 누르면 시간을 칠할 수 있어요. 지금은 스크롤하며 확인할 수 있어요.'}</p><div class="note" style="margin:15px 0">체크한 내용은 이 화면에 임시로 보관돼요. <strong>${demo?'저장하기를 누르면 이 브라우저에 샘플로 저장돼요.':'저장하기를 눌러야 서버에 반영돼요.'}</strong></div><div class="schedule-wrap"><div class="schedule ${editing?'editing':''}"><div class="day">시간</div>${dates.map(date=>`<div class="day">${date.slice(5)} ${days[C.weekday(date)]}</div>`).join('')}${Array.from({length:36},(_,i)=>`<div class="time">${C.clock(i)}</div>${dates.map(date=>{let state=C.availability(draftSlots,date,i);return `<button class="slot ${state}" data-slot="${date}:${i}" data-state="${state}" type="button" aria-label="${date} ${C.clock(i)} ${C.states[state]}" title="${C.states[state]}" ${editing?'':'disabled'}>${state==='free'?'✓':state==='busy'?'×':'·'}</button>`}).join('')}`).join('')}</div></div><div class="legend">${Object.entries(C.states).map(([key,label])=>`<span><i class="swatch ${key}"></i>${label}</span>`).join('')}<span>마지막 칸 23:30–24:00</span></div><div class="row between"><span id="saveState" class="smalltext ${dirty?'accent':'muted'}">${dirty?'저장하지 않은 변경사항이 있어요':raw('availability:'+me.id)?'마지막 저장 '+formatDate(raw('availability:'+me.id).updated_at,true):'아직 입력하지 않았어요.'}</span><button type="button" class="subtle small" data-action="discardSchedule" ${!dirty||scheduleSaving?'disabled':''}>변경 취소</button></div></div>`;
}

function bindPaint(){
 let stroke=null;const grid=$('.schedule');
 const paint=el=>{
  if(!editing||scheduleSaving||!stroke||!el?.dataset.slot||!grid.contains(el))return;
  stroke.apply(draftSlots,el.dataset.slot);const state=slotValue(el.dataset.slot);
  el.className='slot '+state;el.dataset.state=state;el.title=C.states[state];el.textContent={free:'✓',busy:'×',unknown:'·'}[state];
  el.setAttribute('aria-label',el.getAttribute('aria-label').replace(/ (가능|불가|미정)$/,' '+C.states[state]));
  scheduleDirty();updateSaveState();
 };
 const begin=el=>{stroke=C.scheduleStroke(brush,slotValue(el.dataset.slot));paint(el)};
 grid.addEventListener('pointerdown',e=>{if(!editing||scheduleSaving||e.button!==0||!e.target.dataset.slot)return;e.preventDefault();e.target.focus({preventScroll:true});begin(e.target);grid.setPointerCapture(e.pointerId)});
 grid.addEventListener('pointermove',e=>{if(stroke)paint(document.elementFromPoint(e.clientX,e.clientY))});
 const end=()=>stroke=null;grid.addEventListener('pointerup',end);grid.addEventListener('pointercancel',end);grid.addEventListener('lostpointercapture',end);
 grid.addEventListener('keydown',e=>{if((e.key===' '||e.key==='Enter')&&!e.repeat&&editing&&!scheduleSaving&&e.target.dataset.slot){e.preventDefault();begin(e.target);end()}});
 grid.addEventListener('click',e=>{if(e.detail===0&&editing&&!scheduleSaving&&e.target.dataset.slot){begin(e.target);end()}});
 $('#weekStart')?.addEventListener('change',e=>{weekStart=e.target.value||C.isoDate();render()});
}

async function save(action,id,payload={},revision=raw(id)?.revision??null){
 if(demo){demoWrite(action,id,payload);persistDemo();return}
 const {data:result,error}=await client.rpc('aerock_v2_write',{p_action:action,p_id:id,p_data:payload,p_revision:revision});if(error){const e=new Error(error.message);if(action!=='availability'&&error.message.includes('다른 사람이 수정')){await load();e.message='다른 부원이 먼저 수정했어요. 새로고침한 뒤 다시 확인해주세요.'}throw e;}if(result?.id&&result?.kind){records=records.filter(r=>r.id!==result.id);records.push(result)}try{await load()}catch(e){toast('저장은 완료됐어요. 다른 변경사항은 새로고침하면 확인할 수 있어요.')}return result;
}
async function load(){const [{data:rs,error},{data:ps,error:pe}]=await Promise.all([client.from('aerock_v2').select('*').order('updated_at'),client.rpc('aerock_member_directory')]);if(error||pe)throw new Error((error||pe).message);records=rs||[];profiles=ps||[];if(!profiles.some(p=>p.id===me.id))profiles.push(me)}
function songDetail(id){let s=data(id),event=data(s.event_id),isManager=!!s.event_id&&manage(s);let open=!event||new Date(event.session_deadline)>new Date()||s.recruit_open;
 const body=`<div class="row between"><span class="muted">${esc(s.artist)} · ${esc(event?.title||'프리폼')}</span>${badge(s.event_id?s.status:'프리폼',true)}</div>${s.reference?`<p style="margin-top:18px"><a href="${safeUrl(s.reference)}" target="_blank" rel="noopener noreferrer">레퍼런스 듣기 ↗</a></p>`:''}<p class="muted smalltext">${s.duration?`예상 연주 시간 ${Math.floor(s.duration/60)}분 ${s.duration%60}초 · `:''}${s.event_id?'담당 '+esc(s.manager_id?name(s.manager_id):'미배정'):''}</p>${s.notes?`<div class="note" style="white-space:pre-wrap">${esc(s.notes)}</div>`:''}<h3 style="margin-top:25px">세션 ${s.event_id?'신청·확정':'참여'}</h3>${s.parts.map(part=>{let entries=s.entries.filter(e=>e.part===part),own=entries.find(e=>e.user_id===me.id),filled=entries.some(e=>e.status==='confirmed');return `<div class="list-row"><div><strong>${esc(part)}</strong><p>${entries.map(e=>esc(name(e.user_id))+' · '+(e.status==='confirmed'?'확정':'신청 중')).join('<br>')||'함께할 부원을 기다려요'}</p></div><div>${own?(own.status==='pending'||!s.event_id?`<button type="button" class="subtle small" data-action="withdraw" data-id="${id}" data-part="${esc(part)}">${s.event_id?'신청 취소':'참여 취소'}</button>`:badge('참여 확정')):open&&!filled?`<button type="button" class="small" data-action="join" data-id="${id}" data-part="${esc(part)}">${s.event_id?'신청':'참여'}</button>`:badge(filled?'모집 완료':'마감')}</div></div>`}).join('')}${isManager?`<hr><h3>세션 관리</h3>${s.entries.map(e=>`<div class="list-row"><span>${esc(e.part)} · ${esc(name(e.user_id))}</span><div class="row">${e.status==='pending'?`<button type="button" class="small" data-action="entryConfirm" data-id="${id}" data-user="${e.user_id}" data-part="${esc(e.part)}">확정</button>`:''}<button type="button" class="danger small" data-action="entryRemove" data-id="${id}" data-user="${e.user_id}" data-part="${esc(e.part)}">해제</button></div></div>`).join('')}<div class="actions">${btn('참여자 추가·교체','addMember',id,'secondary')}${btn(s.recruit_open?'추가 모집 닫기':'추가 모집 열기','recruit',id,'secondary')}${btn('준비 사항 수정','songNotes',id,'secondary')}</div>`:''}${chair()&&s.event_id?`<hr><h3>회장단 관리</h3>${select('담당 합주부장','manager',[['','미배정'],...profiles.filter(p=>p.role.startsWith('leader')).map(p=>[p.id,p.display_name])],s.manager_id||'')}${select('공연 선정 결과','songStatus',['모집 중','공연 확정','보류','미선정'].map(v=>[v,v]),s.status)}${btn('담당·선정 결과 저장','songManage',id,'')}`:''}${!s.event_id?`<hr>${btn('공연에 이 곡 신청하기','importSong',id,'secondary')}`:''}${chair()?`<hr>${btn('곡 삭제','removeSong',id,'danger')}`:''}`;
 openModal(esc(s.title),body);
}
function safeUrl(u){try{let url=new URL(u);return ['https:','http:'].includes(url.protocol)?esc(url.href):'#'}catch{return '#'}}
async function compress(file){if(!file)return '';if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)throw new Error('JPG·PNG·WebP, 10MB 이하 이미지를 선택하세요.');let img=await createImageBitmap(file),canvas=document.createElement('canvas'),ratio=Math.min(1,1200/Math.max(img.width,img.height));canvas.width=img.width*ratio;canvas.height=img.height*ratio;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);img.close();let result=canvas.toDataURL('image/webp',.8);if(result.length>1e6)throw new Error('이미지가 너무 큽니다. 더 작은 이미지를 선택하세요.');return result}
function eventForm(id){let e=data(id)||{};openModal(id?'공연 수정':'새 공연 만들기',field('공연명','title',e.title,'text',true)+field('공연 날짜·시간 (한국 시간)','date',localInput(e.date),'datetime-local',true)+field('장소','location',e.location)+`<div class="two">${field('곡 신청 마감','song_deadline',localInput(e.song_deadline),'datetime-local',true)}${field('세션 신청 마감','session_deadline',localInput(e.session_deadline),'datetime-local',true)}</div>`+field('공연 포스터 (JPG·PNG·WebP)','poster','','file')+`<label class="row"><input type="checkbox" name="removePoster">포스터 삭제 / 제작중으로 표시</label>`+textarea('공연 안내','notes',e.notes),'저장하기',async(f)=>{let file=f.get('poster');let payload={title:f.get('title').trim(),date:f.get('date')+':00+09:00',location:f.get('location').trim(),song_deadline:f.get('song_deadline')+':00+09:00',session_deadline:f.get('session_deadline')+':00+09:00',notes:f.get('notes'),poster:f.get('removePoster')?'':e.poster||''};if(file?.size)payload.poster=await compress(file);if(new Date(payload.song_deadline)>new Date(payload.session_deadline)||new Date(payload.session_deadline)>new Date(payload.date))throw new Error('곡 마감 → 세션 마감 → 공연 순서로 날짜를 설정하세요.');await save('event',id||newId(),payload,e.revision??null);closeModal();render();toast('공연을 저장했어요')});$('#f_poster').accept='image/jpeg,image/png,image/webp'}
function songForm(eventId='',source=null){let s=source||{};openModal(eventId?'공연곡 신청':'프리폼 곡 등록',field('곡명','title',s.title,'text',true)+field('아티스트','artist',s.artist,'text',true)+`<div class="field"><label>필요한 세션</label><div class="check-list">${[...new Set([...PARTS,...(s.parts||[])])].map(p=>`<label><input type="checkbox" name="parts" value="${esc(p)}" ${(s.parts||[]).includes(p)?'checked':''}>${esc(p)}</label>`).join('')}</div></div>`+field('추가 파트 (쉼표로 구분, 선택)','extra')+field('레퍼런스 링크 (선택)','reference',s.reference,'url')+`<div class="two">${field('예상 연주 시간 · 분','minutes',s.duration?Math.floor(s.duration/60):'','number')}${field('초','seconds',s.duration?s.duration%60:'','number')}</div>`+textarea('비고 · 합주 목적이나 알릴 내용 (선택)','notes',s.notes)+(source?'<p class="note">기존 참여자는 공연곡의 신청 상태로 복사돼요. 프리폼 원본은 유지돼요.</p>':''),'등록하기',async f=>{let parts=[...new Set([...f.getAll('parts'),...f.get('extra').split(',').map(s=>s.trim()).filter(Boolean)])];if(!parts.length||parts.length>12)throw new Error('파트를 1~12개 선택하세요.');let minutes=Number(f.get('minutes')),seconds=Number(f.get('seconds'));if(minutes<0||seconds<0||seconds>59)throw new Error('연주 시간을 확인하세요.');await save('song',newId(),{event_id:eventId||null,title:f.get('title').trim(),artist:f.get('artist').trim(),parts,reference:f.get('reference'),duration:minutes*60+seconds,notes:f.get('notes'),...(source?{source_id:source.id}:{})});closeModal();render();toast('곡을 등록했어요')})}
function practiceDetail(id){let r=data(id);let users=practiceUsers(r);openModal('합주 상세',`<div class="row between"><h3>${esc(r.location)}</h3>${badge(r.status,true)}</div>${r.segments.map(s=>`<div class="segment"><strong>${esc(data(s.song_id)?.title||'삭제된 곡')}</strong><p class="muted smalltext" style="margin:8px 0 0">${formatDate(s.start)} ${time(s.start)}–${time(s.end)} · ${esc(s.room)}</p></div>`).join('')}${r.notes?`<p style="white-space:pre-wrap">${esc(r.notes)}</p>`:''}<h3>참여자 확인 ${users.filter(u=>responseFor(r,u)?.status==='확인 완료').length}/${users.length}</h3>${users.map(u=>{let a=responseFor(r,u);return `<div class="list-row"><span>${esc(name(u))}</span>${badge(a?.status||'확인 필요',a?.status==='조율 요청')}</div>${a?.reason?`<div class="request">${esc(a.reason)}</div>`:''}`}).join('')}${chair()||(leader()&&r.owner_id===me.id)?`<div class="actions">${btn('일정 수정','practiceEdit',id,'')}${r.status!=='취소'?btn('예약 취소로 표시','practiceCancel',id,'danger'):''}</div>`:''}`)}
function bookings(){return rows('rehearsal').filter(r=>r.status!=='취소').flatMap(r=>r.segments.map(s=>({...s,users:C.members(data(s.song_id)||{}),rehearsal_id:r.id,location:r.location})))}
function planner(eventId){let songs=rows('song').filter(s=>s.event_id===eventId&&s.status==='공연 확정'&&manage(s));if(!songs.length)return toast('담당 공연 확정 곡이 있어야 합주를 등록할 수 있어요.');openModal('합주 일정 잡기',`<p class="muted">곡을 선택하면 확정 참여자의 시간표를 합쳐 확인해요.</p><div class="check-list">${songs.map(s=>`<label><input type="checkbox" name="songs" value="${s.id}">${esc(s.title)}</label>`).join('')}</div><hr><div class="two">${field('추천 시작일','from',C.isoDate(),'date',true)}${select('곡별 합주 길이','duration',[['60','1시간'],['90','1시간 30분'],['120','2시간'],['180','3시간']],'120')}</div>${btn('공통 시간 확인','recommend','','secondary')}<div id="recommendations" style="margin-top:20px"></div>`,'직접 시간 입력',async f=>{let ids=f.getAll('songs');if(!ids.length)throw new Error('곡을 선택하세요.');closeModal();practiceForm(null,ids)});}
function recommend(){let form=$('#modalForm'),f=new FormData(form),ids=f.getAll('songs');if(!ids.length)return toast('곡을 선택하세요.');let users=[...new Set(ids.flatMap(id=>C.members(data(id))))];if(!users.length)return toast('확정된 참여자가 없습니다.');let av={};for(let r of rows('availability'))av[r.owner_id]=r.slots;let dates=Array.from({length:7},(_,i)=>C.dateAdd(f.get('from'),i));let duration=Number(f.get('duration')),total=duration*ids.length;if(total>1080)return toast('선택한 곡의 총 합주 시간이 하루 범위를 넘어요. 곡 수나 곡별 길이를 줄여주세요.');let results=C.recommendations({dates,duration:total,users,slots:av,bookings:bookings()}).filter(r=>new Date(r.start)>new Date());window.currentRecommendations=results;let heat=C.recommendations({dates,duration:30,users,slots:av,bookings:bookings()});window.currentHeat=heat;let heatMap=new Map(heat.map((r,i)=>[r.start,{r,i}]));let heatHTML=`<details><summary>시간표 겹쳐 보기 · 가능 인원 / 전체 인원</summary><div class="schedule-wrap" style="max-height:360px;margin-top:12px"><div class="schedule"><div class="day">시간</div>${dates.map(d=>`<div class="day">${d.slice(5)}</div>`).join('')}${Array.from({length:36},(_,slot)=>`<div class="time">${C.clock(slot)}</div>${dates.map(d=>{let item=heatMap.get(d+'T'+C.clock(slot)+':00+09:00'),r=item.r;return `<button type="button" class="slot" style="background:rgba(255,113,57,${.07+.75*r.free.length/users.length})" data-action="heatDetail" data-id="${item.i}" aria-label="${d} ${C.clock(slot)} 가능 ${r.free.length}명">${r.free.length}/${users.length}</button>`}).join('')}`).join('')}</div></div><div id="heatDetail" class="smalltext" style="margin:12px 0"></div></details>`;let labels=['가능','불가','미정'];$('#recommendations').innerHTML=`${heatHTML}<p class="smalltext muted">${ids.length}곡 · 곡별 ${duration}분 · 총 ${total}분 · ${users.length}명 · 입력 완료 ${users.filter(u=>raw('availability:'+u)).length}명 · 선택일부터 7일간</p>${results.slice(0,6).map((r,i)=>`<div class="segment"><div class="row between"><strong>${formatDate(r.start)} ${time(r.start)}–${time(r.end)}</strong><button type="button" class="small" data-action="useTime" data-id="${i}">선택</button></div><p class="smalltext" style="margin:10px 0 0">${['free','busy','unknown'].map((k,j)=>`${labels[j]} ${r[k].length}명${r[k].length?' ('+r[k].map(name).map(esc).join(', ')+')':''}`).join('<br>')}</p></div>`).join('')||empty('추천할 미래 시간이 없어요')}`}
function practiceForm(id,ids=[],suggestion){let r=data(id);let segs=r?.segments||(suggestion?C.rehearsalSegments(ids,suggestion.start,suggestion.minutes):ids.map(sid=>({song_id:sid,start:'',end:'',room:''})));openModal(id?'합주 일정 수정':'예약한 합주 등록',`<p class="note">외부에서 합주실 예약 후 등록해주세요. 날짜·시간은 한국 시간 기준이며, 수정하면 참여자의 재확인이 필요해요.</p>${field('합주실 이름·지점','location',r?.location,'text',true)}${segs.map((s,i)=>`<div class="segment" data-song="${s.song_id}"><h3>${esc(data(s.song_id)?.title)}</h3><div class="two">${field('시작','start_'+i,localInput(s.start),'datetime-local',true)}${field('종료','end_'+i,localInput(s.end),'datetime-local',true)}</div>${field('방 이름·번호','room_'+i,s.room,'text',true)}</div>`).join('')}${textarea('합주 안내 (선택)','notes',r?.notes)}<div id="conflictMessage"></div>`,'예약 일정 저장',async f=>{let payload={location:f.get('location').trim(),status:'예약 완료',notes:f.get('notes'),segments:segs.map((s,i)=>({song_id:s.song_id,start:f.get('start_'+i)+':00+09:00',end:f.get('end_'+i)+':00+09:00',room:f.get('room_'+i).trim()}))};for(let s of payload.segments)if(new Date(s.start)>=new Date(s.end))throw new Error('종료 시간은 시작 시간 이후여야 합니다.');let conflicts=[];for(let s of payload.segments){let us=C.members(data(s.song_id));for(let b of bookings().filter(b=>b.rehearsal_id!==id)){if(C.overlaps(s,b)&&(b.users.some(u=>us.includes(u))||(payload.location===b.location&&s.room===b.room)))conflicts.push(esc(data(s.song_id).title)+' 참여자의 기존 합주와 겹칩니다.')}}for(let i=0;i<payload.segments.length;i++)for(let j=i+1;j<payload.segments.length;j++){let a=payload.segments[i],b=payload.segments[j];if(C.overlaps(a,b)&&(a.room===b.room||C.members(data(a.song_id)).some(u=>C.members(data(b.song_id)).includes(u))))conflicts.push('같은 방 또는 참여자의 곡별 연습 시간이 겹칩니다. 곡별 시간 구간을 나눠주세요.')}if(conflicts.length)throw new Error([...new Set(conflicts)].join(' '));await save('rehearsal',id||newId(),payload,r?.revision??null);closeModal();render();toast('합주 일정을 등록했어요')})}
function loginView(){$('#app').innerHTML=`<div class="login card"><div class="wordmark">AER<span>O</span>CK.</div><div class="eyebrow">MAKE OUR NEXT STAGE</div><h1>우리의 다음 무대,<br>여기서 시작해요.</h1><p>곡 신청부터 시간표, 합주 일정까지.<br>AEROCK 부원을 위한 공간입니다.</p>${btn('카카오로 시작하기','login','','kakao')}<p class="smalltext">처음 방문하면 이름을 입력하고 회장단의 승인을 기다려주세요.</p><details><summary class="muted smalltext">아이디로 로그인</summary><form id="staffLogin" style="margin-top:18px">${field('아이디','username','','text',true)}${field('비밀번호','password','','password',true)}<button type="submit">로그인</button></form></details><p id="authError" class="error"></p></div>`;$('#staffLogin').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);let {error}=await client.auth.signInWithPassword({email:f.get('username').trim()+'@'+AEROCK_CONFIG.domain,password:f.get('password')});if(error)$('#authError').textContent='아이디 또는 비밀번호를 확인해주세요.'}}
function pendingView(){$('#app').innerHTML=`<div class="login card"><div class="wordmark">AEROCK.</div><h2>${me.status==='pending'?'가입 승인 대기 중':'이용이 제한된 계정입니다'}</h2><p>회장단이 확인할 수 있도록 실제 이름을 입력해주세요.</p><p><strong>${esc(me.display_name||'이름 미입력')}</strong></p><div class="row">${btn('이름 입력·수정','name','','')}${btn('승인 확인','refresh','','secondary')}${btn('로그아웃','logout','','subtle')}</div></div>`}
async function boot(){if(demo){seedDemo();loadScheduleDraft();render();return}if(!window.supabase||!window.AEROCK_CONFIG){$('#app').innerHTML=empty('연결을 불러오지 못했어요','인터넷 연결을 확인하고 새로고침해주세요.');return}client=supabase.createClient(AEROCK_CONFIG.url,AEROCK_CONFIG.anonKey);let {data:{session}}=await client.auth.getSession();await authenticate(session?.user);client.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_IN'||event==='SIGNED_OUT')setTimeout(()=>authenticate(session?.user),0)})}
async function authenticate(user){if(!user){me=null;render();return}const preserveSchedule=me?.id===user.id&&(dirty||(page==='schedule'&&editing));const {data:p,error}=await client.from('member_profiles').select('id,display_name,role,status').eq('id',user.id).single();if(error){$('#app').innerHTML=empty('회원 정보를 불러오지 못했어요','잠시 후 새로고침하거나 회장단에 문의해주세요.');return}me=p;if(me.status==='active'){try{await load();if(!preserveSchedule)loadScheduleDraft();if(!window.aerockSubscription){window.aerockSubscription=client.channel('aerock-v2').on('postgres_changes',{event:'*',schema:'public',table:'aerock_v2'},()=>{clearTimeout(realtimeTimer);realtimeTimer=setTimeout(async()=>{try{await load();if(!dirty&&!(page==='schedule'&&editing)&&!scheduleSaving&&!$('#modal').open){loadScheduleDraft();render();}else toast('새 변경사항이 있어요. 현재 입력을 마친 뒤 새로고침해주세요.')}catch(e){toast(e.message)}},500)}).subscribe()}}catch(e){$('#app').innerHTML=empty('새 버전을 준비하고 있어요',esc(e.message));return}}render()}
document.addEventListener('click',async e=>{let el=e.target.closest('[data-action]');if(!el||busy)return;e.preventDefault();let a=el.dataset.action,id=el.dataset.id;if(scheduleSaving&&['nav','scheduleWeek','brush','editSchedule','discardSchedule','refresh'].includes(a))return;try{await handle(a,id,el)}catch(err){toast(err.message)}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.song-card')){e.preventDefault();songDetail(e.target.dataset.id)}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
async function handle(a,id,el){
 if(a==='close'){closeModal();return}
 if(a==='nav'){if(dirty&&id!=='schedule'){openModal('시간표 변경사항',`<p>저장하지 않은 변경사항이 있어요. 저장한 뒤 이동해주세요.</p>`);return}page=id;selectedEvent=null;onlyMine=false;render();window.scrollTo(0,0)}
 else if(a==='event'){page='events';selectedEvent=id;eventTab='songs';render()}
 else if(a==='eventBack'){selectedEvent=null;render()}
 else if(a==='eventTab'){eventTab=id;render()}
 else if(a==='managed'){page='events';selectedEvent=null;onlyMine=true;render()}
 else if(a==='allEvents'){onlyMine=false;render()}
 else if(a==='eventForm')eventForm(id);
 else if(a==='songForm')songForm(id);
 else if(a==='songDetail')songDetail(id);
 else if(a==='join'||a==='withdraw'){await save(a,id,{part:el.dataset.part});songDetailRefresh(id);toast(a==='join'?'참여 신청을 반영했어요':'참여를 취소했어요')}
 else if(a==='entryConfirm'||a==='entryRemove'){await save('entry',id,{user_id:el.dataset.user,part:el.dataset.part,status:a==='entryConfirm'?'confirmed':'remove'});songDetailRefresh(id)}
 else if(a==='songManage'){await save('song_manage',id,{manager_id:$('#f_manager').value,status:$('#f_songStatus').value});songDetailRefresh(id);toast('담당과 선정 결과를 저장했어요')}
 else if(a==='recruit'){await save('song_manage',id,{recruit_open:!data(id).recruit_open});songDetailRefresh(id)}
 else if(a==='songNotes'){let s=data(id);closeModal();openModal('곡 준비 사항',textarea('비고·악보·편곡 준비 사항','notes',s.notes),'저장',async f=>{await save('song_manage',id,{notes:f.get('notes')});songDetailRefresh(id)})}
 else if(a==='removeSong'){closeModal();openModal('곡 삭제',`<p>“${esc(data(id).title)}”을 목록에서 삭제할까요?</p><p class="muted">기록은 보존되고 목록에서 숨겨집니다.</p>`,'삭제',async()=>{await save('remove_song',id);closeModal();render();toast('곡을 삭제했어요')})}
 else if(a==='addMember'){let s=data(id);closeModal();openModal('참여자 추가·교체',select('파트','part',s.parts.map(p=>[p,p]))+select('부원','user',profiles.filter(p=>p.status==='active').map(p=>[p.id,p.display_name]))+'<p class="muted smalltext">이미 채워진 파트는 기존 참여자를 먼저 해제해주세요.</p>','참여 확정',async f=>{await save('entry',id,{user_id:f.get('user'),part:f.get('part'),status:'confirmed'});songDetailRefresh(id)})}
 else if(a==='importSong'){let s=data(id),ev=activeEvents().filter(e=>new Date(e.song_deadline)>new Date());if(!ev.length)return toast('곡을 모집 중인 공연이 없어요.');closeModal();openModal('공연에 신청하기',select('공연 선택','event',ev.map(e=>[e.id,e.title])),'다음',async f=>{closeModal();songForm(f.get('event'),s)})}
 else if(a==='scheduleWeek'){weekStart=C.dateAdd(weekStart,Number(id));render()}
 else if(a==='brush'){if(!Object.hasOwn(C.states,id))return;brush=id;sessionStorage.setItem('aerock-schedule-brush',brush);document.querySelectorAll('[data-action="brush"]').forEach(b=>{b.classList.toggle('selected',b.dataset.id===brush);b.setAttribute('aria-pressed',String(b.dataset.id===brush))})}
 else if(a==='editSchedule'){editing=!editing;render()}
 else if(a==='saveSchedule'){await saveSchedule()}
 else if(a==='discardSchedule'){openModal('시간표 변경 취소','<p>저장하지 않은 시간표 변경을 취소하고 서버에 저장된 시간표를 다시 불러올까요?</p>','변경 취소',async()=>{if(!demo)await load();loadScheduleDraft();closeModal();render();toast('저장된 시간표를 불러왔어요')})}
 else if(a==='planner'){planner(id)}
 else if(a==='recommend')recommend();
 else if(a==='heatDetail'){let r=window.currentHeat[Number(id)];$('#heatDetail').innerHTML=`<strong>${formatDate(r.start)} ${time(r.start)}</strong><br>`+['free','busy','unknown'].map(k=>`${C.states[k]}: ${r[k].map(name).map(esc).join(', ')||'없음'}`).join('<br>')}
 else if(a==='useTime'){let f=new FormData($('#modalForm')),ids=f.getAll('songs'),r=window.currentRecommendations[Number(id)];closeModal();practiceForm(null,ids,{...r,minutes:Number(f.get('duration'))})}
 else if(a==='practiceDetail')practiceDetail(id);
 else if(a==='practiceEdit'){closeModal();practiceForm(id)}
 else if(a==='practiceCancel'){let r=data(id);closeModal();openModal('예약 취소 표시',`<p>사이트에서 취소로 표시할까요? 합주실의 실제 예약 취소는 별도로 진행해야 해요.</p>`,'취소로 표시',async()=>{let payload=structuredClone(raw(id).payload);payload.status='취소';await save('rehearsal',id,payload);closeModal();render()})}
 else if(a==='ack'){let r=data(id);await save('response','response:'+id+':'+me.id,{rehearsal_id:id,schedule_revision:r.revision,status:'확인 완료',reason:''});render();toast('일정을 확인했어요')}
 else if(a==='request'){let r=data(id);openModal('조율이 필요해요',textarea('보류·수정이 필요한 내용을 적어주세요','reason'),'요청 보내기',async f=>{let reason=f.get('reason').trim();if(!reason)throw new Error('사유를 입력해주세요.');await save('response','response:'+id+':'+me.id,{rehearsal_id:id,schedule_revision:r.revision,status:'조율 요청',reason});closeModal();render();toast('담당 합주부장이 확인할 수 있도록 등록했어요')})}
 else if(a==='name'){openModal('이름 입력',field('이름','name',me.display_name,'text',true),'저장',async f=>{await save('name',me.id,{name:f.get('name')});me.display_name=f.get('name');closeModal();render()})}
 else if(a==='members'){if(demo){$('#pendingMembers').innerHTML=empty('현재 승인 대기 회원이 없어요');return}let {data:ps,error}=await client.from('member_profiles').select('id,display_name,status').eq('status','pending');if(error)throw error;$('#pendingMembers').innerHTML=ps.map(p=>`<div class="list-row"><strong>${esc(p.display_name||'이름 미입력')}</strong>${p.display_name?.trim()?btn('가입 승인','approve',p.id,''):'<span class="muted">이름 입력 대기</span>'}</div>`).join('')||empty('현재 승인 대기 회원이 없어요')}
 else if(a==='approve'){await save('approve',id);await handle('members')}
 else if(a==='refresh'){if(dirty)return toast('시간표 변경사항을 먼저 저장해주세요.');if(!demo){let {data:{session}}=await client.auth.getSession();await authenticate(session?.user)}else{seedDemo();loadScheduleDraft();render()}toast('최신 상태로 확인했어요')}
 else if(a==='login'){let {error}=await client.auth.signInWithOAuth({provider:'kakao',options:{redirectTo:location.origin+location.pathname}});if(error)throw error}
 else if(a==='logout'){if(demo){toast('시안에서는 실제 로그인을 사용하지 않아요.');return}await client.auth.signOut();location.reload()}
 else if(a==='resetDemo'){localStorage.removeItem('aerock-v2-demo');seedDemo();loadScheduleDraft();render();toast('샘플 데이터를 초기화했어요')}
}
function songDetailRefresh(id){closeModal();render();songDetail(id)}
window.addEventListener('storage',e=>{if(!demo||e.key!=='aerock-v2-demo')return;try{records=JSON.parse(e.newValue||'[]');if(!dirty&&!scheduleSaving&&!$('#modal').open){loadScheduleDraft();render()}else toast('다른 샘플 사용자의 변경사항이 있어요. 입력을 마친 뒤 새로고침해주세요.')}catch{}});
function persistDemo(){localStorage.setItem('aerock-v2-demo',JSON.stringify(records))}
function seedDemo(){profiles=[{id:'demo-me',display_name:'김민규',role:'member',status:'active'},{id:'demo-chair',display_name:'이서준',role:'president',status:'active'},{id:'demo-leader',display_name:'박지우',role:'leader1',status:'active'},{id:'demo-bass',display_name:'최유진',role:'member',status:'active'},{id:'demo-drums',display_name:'정하린',role:'member',status:'active'},{id:'demo-keys',display_name:'한도윤',role:'member',status:'active'}];me=profiles.find(p=>p.id===sessionStorage.getItem('aerock-demo-persona'))||profiles[0];let saved=localStorage.getItem('aerock-v2-demo');if(saved){try{records=JSON.parse(saved);return}catch{}}records=[];const push=(id,kind,payload,owner='demo-leader')=>records.push({id,kind,payload,owner_id:owner,revision:1,updated_at:new Date().toISOString()});let d=C.dateAdd(C.isoDate(),14),later=C.dateAdd(d,7);push('event-autumn','event',{title:'FALL, AWAY',date:d+'T18:00:00+09:00',location:'청계천 야외무대',song_deadline:C.dateAdd(d,-7)+'T23:59:00+09:00',session_deadline:C.dateAdd(d,-4)+'T23:59:00+09:00',poster:'',notes:'가을 저녁, 우리의 음악으로 채우는 무대. 함께 연주할 곡을 신청해주세요.'},'demo-chair');push('event-regular','event',{title:'AEROCK 정기공연',date:later+'T18:00:00+09:00',location:'공연장 협의 중',song_deadline:C.dateAdd(d,-2)+'T23:59:00+09:00',session_deadline:d+'T23:59:00+09:00',poster:'',notes:''},'demo-chair');let lineup=[['메인보컬','demo-me'],['리드기타','demo-leader'],['베이스','demo-bass'],['드럼','demo-drums'],['키보드(메인)','demo-keys']].map(([part,user_id])=>({part,user_id,status:'confirmed'}));push('song-hero','song',{event_id:'event-autumn',title:'히로인',artist:'back number',parts:lineup.map(e=>e.part),entries:lineup,manager_id:'demo-leader',status:'공연 확정',reference:'',duration:268,notes:'라이브 버전을 기준으로 연습해요.'});push('song-bloom','song',{event_id:'event-autumn',title:'피었습니다.',artist:'N.Flying',parts:lineup.map(e=>e.part),entries:lineup,manager_id:'demo-leader',status:'공연 확정',reference:'',duration:192,notes:''});push('song-letter','song',{event_id:'event-autumn',title:'LETTER',artist:'유다빈밴드',parts:['메인보컬','리드기타','리듬기타','베이스','드럼'],entries:[{part:'리드기타',user_id:'demo-leader',status:'confirmed'}],manager_id:'demo-leader',status:'모집 중',reference:'',duration:208,notes:'리듬기타와 보컬을 모집하고 있어요.'});push('song-free','song',{event_id:null,title:'Lost Stars',artist:'Adam Levine',parts:['메인보컬','리드기타','키보드(메인)'],entries:[{part:'리드기타',user_id:'demo-leader',status:'confirmed'}],manager_id:null,status:'모집 중',notes:'어쿠스틱으로 가볍게 맞춰보고 싶어요. 초보자도 환영해요!',duration:270});for(let p of profiles){let slots={};for(let day=0;day<21;day++)for(let i=0;i<36;i++)slots[C.dateAdd(C.isoDate(),day)+':'+i]=i>=24&&i<32?'free':i>=6&&i<22?'busy':'unknown';push('availability:'+p.id,'availability',{slots},p.id)}let soon=C.dateAdd(C.isoDate(),3);push('practice-next','rehearsal',{location:'호랑이 합주실 · 홍대점',status:'예약 완료',segments:[{song_id:'song-hero',start:soon+'T19:00:00+09:00',end:soon+'T20:30:00+09:00',room:'A룸'},{song_id:'song-bloom',start:soon+'T20:30:00+09:00',end:soon+'T22:00:00+09:00',room:'A룸'}],notes:'시작 10분 전 도착해주세요. 개인 악기와 악보를 준비해주세요.'});persistDemo()}
function demoWrite(action,id,p){let r=raw(id),obj=r?structuredClone(r.payload):{},kind=r?.kind;if(action==='name'){me.display_name=p.name;return}if(action==='event'){kind='event';obj=p}else if(action==='song'){kind='song';obj={...p,entries:p.source_id?(data(p.source_id)?.entries||[]).filter(e=>p.parts.includes(e.part)).map(e=>({...e,status:'pending'})):[],manager_id:null,status:'모집 중'}}else if(action==='song_manage'){obj={...obj,...p}}else if(action==='remove_song'){obj.deleted=true}else if(['join','withdraw','entry'].includes(action)){let uid=action==='entry'?p.user_id:me.id,state=action==='join'?(obj.event_id?'pending':'confirmed'):p.status;if(state==='confirmed'&&obj.entries.some(e=>e.part===p.part&&e.status==='confirmed'&&e.user_id!==uid))throw new Error('이미 채워진 파트입니다.');obj.entries=obj.entries.filter(e=>!(e.user_id===uid&&e.part===p.part));if(action!=='withdraw'&&state!=='remove')obj.entries.push({user_id:uid,part:p.part,status:state})}else if(['availability','rehearsal','response'].includes(action)){kind=action;obj=p}records=records.filter(x=>x.id!==id);records.push({id,kind,payload:obj,revision:(r?.revision||0)+1,owner_id:r?.owner_id||me.id,updated_at:new Date().toISOString()})}
boot().catch(e=>{$('#app').innerHTML=empty('연결 오류',esc(e.message))});
